sys_ui_action.script:
function onClick() {
  var id = g_form.getUniqueValue();
  if (!id) { alert('Save the record first.'); return; }

  var REPORT_ID = '09d4e83ac3e83210111afb377d01312c';
  var CHILD_REF_FIELD = 'pettycashmain_ref'; // change if needed

   alert('REPORT_ID in the Print Report is : ' + REPORT_ID);


  var url = '/report_viewer.do'
          + '?sysparm_report_id=' + REPORT_ID
          + '&sysparm_query=' + encodeURIComponent(CHILD_REF_FIELD + '=' + id)
          + '&sysparm_media=print&sysparm_display_value=true';
  window.open(url, '_blank');
}



